void ctl_dl_init (void)
{
	static const Cmd_Array1 cmd_array[] = 
    {
        {(INPUT_GWR	                | INPUT_ON  ) , ctl_dl_gwr_on		    }, 
    	{(INPUT_GWR					     	    ) , ctl_dl_gwr_off	    }, 
    	{(INPUT_IGNITION	        | INPUT_ON  ) , ctl_dl_ign_on		    }, 
    	{(INPUT_IGNITION					    ) , ctl_dl_ign_off	    }, 
    	{(INPUT_BRAKE_STATUS_PRESS		        ) , ctl_dl_brake_press    }, 
    	{(INPUT_SPEED_SET		 	 	        ) , ctl_dl_speed_set	    }
    }; 

    CMD_LUT_INSERT1(cmd_array,EXEC_MODE_NORMAL);
    
	ctl_dl_defer_timeout = timeout_f_create (LOCK_DELAY, ctl_dl_defer_timeout_fnc) ;

	ctl_dl_gwr = timeout_f_create (CTL_DL_GWR_DELAY, ctl_dl_gwr_timeout) ;			
}

